const items = $input.all();

if (items.length === 0) {
  throw new Error("No chapter data received.");
}

let chapters = [];

// Handle Aggregate output
if (items.length === 1) {
  const json = items[0].json;

  if (Array.isArray(json.chapters)) {
    chapters = json.chapters;
  } else if (Array.isArray(json.data)) {
    chapters = json.data;
  } else {
    chapters = items.map(item => item.json);
  }
} else {
  chapters = items.map(item => item.json);
}

if (chapters.length === 0) {
  throw new Error("No chapters found after aggregation.");
}

chapters.sort((a, b) =>
  Number(a.chapter_number || 0) -
  Number(b.chapter_number || 0)
);

const combinedChapters = chapters.map((chapter, index) => {
  const chapterText =
    chapter.output ??
    chapter.text ??
    chapter.content ??
    chapter.chapter ??
    "";

  return `CHAPTER ${chapter.chapter_number || index + 1}: ${chapter.title || ""}

${chapterText}`;
}).join("\n\n========================================\n\n");

return [
  {
    json: {
      topic: chapters[0]?.topic ||
             $('Prompt Library').first().json.chatInput ||
             "",
      chapter_count: chapters.length,
      completed_chapters: combinedChapters
    }
  }
];

const items = $input.all();
const source = items[0].json;

// Get AI Agent output
let outline = source.output || source.text || source.response || "";

// If output is an object, convert it to text
if (typeof outline !== "string") {
  outline = JSON.stringify(outline);
}

// Fallback: find the largest text field
if (!outline) {
  for (const [key, value] of Object.entries(source)) {
    if (typeof value === "string" && value.length > 300) {
      outline = value;
      break;
    }
  }
}

if (!outline) {
  throw new Error("Could not find the Outline Agent output.");
}

// Normalize line endings
outline = outline.replace(/\r\n/g, "\n");

// ----------------------------------------------------
// FIND CHAPTER HEADINGS
// Handles formats such as:
//
// Chapter 1: The Enchanted Illusion
// Chapter 1 — The Enchanted Illusion
// 1. The Enchanted Illusion
// 1. The Enchanted Illusion — What We Think We Know
// **1. The Enchanted Illusion**
// ## Chapter 1: The Enchanted Illusion
// ### 1. The Enchanted Illusion
// ----------------------------------------------------

const headingRegex =
  /^\s*(?:#{1,6}\s*)?(?:\*\*)?\s*(?:Chapter\s*)?(\d{1,2})\s*[\.\:\-\—\–]\s*(.+?)(?:\*\*)?\s*$/gim;

const matches = [...outline.matchAll(headingRegex)];

const chapters = [];

for (let i = 0; i < matches.length; i++) {

  const match = matches[i];

  const chapterNumber = parseInt(match[1], 10);
  const title = match[2]
    .replace(/\*\*/g, "")
    .trim();

  if (chapterNumber < 1 || chapterNumber > 30) {
    continue;
  }

  const start = match.index + match[0].length;

  const end =
    i + 1 < matches.length
      ? matches[i + 1].index
      : outline.length;

  let chapterContent = outline
    .slice(start, end)
    .trim();

  // Remove excessive blank lines
  chapterContent = chapterContent.replace(/\n{3,}/g, "\n\n");

  // Try to find approximate word count
  const wordMatch = chapterContent.match(
    /(?:approx(?:imate)?\s*)?word\s*count\s*[:\-]?\s*~?\s*([\d,]+)/i
  );

  const wordCount = wordMatch
    ? parseInt(wordMatch[1].replace(/,/g, ""), 10)
    : null;

  chapters.push({
    chapter_number: chapterNumber,
    title: title,
    outline: chapterContent,
    approx_word_count: wordCount
  });
}

// Remove duplicates
const seen = new Set();

const uniqueChapters = chapters.filter(chapter => {

  if (seen.has(chapter.chapter_number)) {
    return false;
  }

  seen.add(chapter.chapter_number);
  return true;
});

// Sort by chapter number
uniqueChapters.sort(
  (a, b) => a.chapter_number - b.chapter_number
);

// ----------------------------------------------------
// IMPORTANT:
// If nothing was detected, return diagnostic information
// instead of hiding the problem.
// ----------------------------------------------------

if (uniqueChapters.length === 0) {

  return [{
    json: {
      ERROR: "No chapters detected",
      available_fields: Object.keys(source),
      output_preview: outline.substring(0, 3000)
    }
  }];
}

// Return one item per chapter
return uniqueChapters.map(chapter => ({
  json: {
    topic: source.topic || "",
    chapter_number: chapter.chapter_number,
    title: chapter.title,
    outline: chapter.outline,
    approx_word_count: chapter.approx_word_count
  }
}));

const topicData = $('Prompt Library').first().json;
const finalScriptData = $('Final Script Writer').first().json;
const imageData = $('Image Prompt Generator').first().json;

const topic = topicData.chatInput || "Untitled Project";

const safeName = topic
  .replace(/[<>:"/\\|?*]/g, "")
  .replace(/\s+/g, " ")
  .trim()
  .substring(0, 120) || "Untitled Project";

const projectPath =
  `/home/node/.n8n/YouTubeProjects/${safeName}`;

const finalScript =
  finalScriptData.output ||
  finalScriptData.text ||
  finalScriptData.final_script ||
  finalScriptData.script ||
  "";

const imagePrompts =
  imageData.output ||
  imageData.text ||
  imageData.image_prompts ||
  "";

if (!finalScript) {
  throw new Error("Final Script Writer returned no script.");
}

if (!imagePrompts) {
  throw new Error("Image Prompt Generator returned no image prompts.");
}

return [
  {
    json: {
      topic,
      project_name: safeName,
      project_path: projectPath,

      script_filename: "final_script.txt",
      image_filename: "image_prompt.csv",

      final_script: finalScript,
      image_prompts: imagePrompts
    }
  }
];

const fs = require('fs');

const data = $input.first().json;

if (!data.project_path) {
  throw new Error('Project path is missing.');
}

fs.mkdirSync(data.project_path, {
  recursive: true,
  mode: 0o755
});

return $input.all();

const fs = require('fs');

const data = $input.first().json;

const projectPath = data.project_path;
const finalScript = data.final_script || '';
const imageText = data.image_prompts || '';
const topic = data.topic || 'Untitled Project';

if (!projectPath) {
  throw new Error('Project path is missing.');
}

if (!finalScript) {
  throw new Error('Final script is empty.');
}

if (!imageText) {
  throw new Error('Image prompts are empty.');
}


// ============================================================
// CREATE PROJECT FOLDER
// ============================================================

fs.mkdirSync(projectPath, {
  recursive: true
});


// ============================================================
// LOCK-SAFE WRITE HELPER
// ============================================================
// Writes to a temp file first, then atomically renames it onto the
// real destination. If the rename fails with EACCES / EBUSY / EPERM
// (typical when the destination is open in Excel/another program via
// a Windows bind mount) we do NOT retry the same destination - we
// fall back to a unique, timestamped filename in the SAME directory
// instead of failing the workflow.

const LOCK_ERROR_CODES = new Set(['EACCES', 'EBUSY', 'EPERM']);

function isLockError(err) {
  return !!err && LOCK_ERROR_CODES.has(err.code);
}

function timestampSuffix() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, '0');
  return (
    `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}` +
    `_${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`
  );
}

function uniqueFallbackPath(dir, baseName, ext) {
  const suffix = timestampSuffix();
  let candidate = `${dir}/${baseName}_${suffix}${ext}`;
  let attempt = 1;

  // Guard against two fallbacks landing on the same filename
  // (same-second writes, or a leftover fallback from a prior run).
  while (fs.existsSync(candidate)) {
    attempt += 1;
    candidate = `${dir}/${baseName}_${suffix}_${attempt}${ext}`;
  }

  return candidate;
}

function safeWriteFile(dir, baseName, ext, content, writeOptions) {
  const finalPath = `${dir}/${baseName}${ext}`;
  const tempPath = `${dir}/.${baseName}.${Date.now()}.${Math.random()
    .toString(36)
    .slice(2)}.${Math.random().toString(36).slice(2)}.tmp`;

  let writtenPath = finalPath;
  let usedFallback = false;

  try {
    fs.writeFileSync(tempPath, content, writeOptions);

    try {
      fs.renameSync(tempPath, finalPath);
      writtenPath = finalPath;
    } catch (renameErr) {
      if (!isLockError(renameErr)) {
        throw renameErr;
      }

      const fallbackPath = uniqueFallbackPath(dir, baseName, ext);
      fs.renameSync(tempPath, fallbackPath);
      writtenPath = fallbackPath;
      usedFallback = true;
    }
  } finally {
    if (fs.existsSync(tempPath)) {
      try {
        fs.unlinkSync(tempPath);
      } catch (cleanupErr) {
        // Never fail the workflow over a leftover temp file.
      }
    }
  }

  return {
    path: writtenPath,
    filename: writtenPath.split('/').pop(),
    usedFallback
  };
}


// ============================================================
// SAVE FINAL SCRIPT (lock-safe)
// ============================================================

const scriptResult = safeWriteFile(projectPath, 'final_script', '.txt', finalScript, 'utf8');


// ============================================================
// PARSE IMAGE PROMPTS  (unchanged)
// ============================================================

const lines = imageText.split(/\r?\n/);

const rows = [];

let current = null;
let currentChapter = '';
let insidePrompt = false;


function cleanText(text) {
  return String(text || '')
    .replace(/\*\*/g, '')
    .replace(/`/g, '')
    .trim();
}


function saveCurrentScene() {

  if (!current) {
    return;
  }

  if (!current.prompt.trim()) {
    throw new Error(
      `Scene ${current.shot} does not contain an Image prompt.`
    );
  }

  rows.push({
    chapter: current.chapter || currentChapter || '',
    shot: current.shot,
    character: current.character || '',
    prompt: current.prompt.trim()
  });
}


for (const rawLine of lines) {

  const line = rawLine.trim();

  if (!line) {
    continue;
  }

  const sceneMatch = line.match(
    /^(?:#+\s*)?(?:[•>*\-]\s*)*Scene\s+(\d+)/i
  );

  if (sceneMatch) {

    saveCurrentScene();

    current = {
      chapter: currentChapter,
      shot: Number(sceneMatch[1]),
      character: '',
      prompt: ''
    };

    insidePrompt = false;

    continue;
  }

  if (!current) {
    continue;
  }

  const chapterField = line.match(
    /^(?:[•>*\-]\s*)*(?:\*\*)?\s*Chapter\s*(?:\*\*)?\s*:\s*(.*)$/i
  );

  if (chapterField) {
    current.chapter = cleanText(chapterField[1]);
    currentChapter = current.chapter;
    insidePrompt = false;
    continue;
  }

  const chapterHeading = line.match(
    /^(?:#+\s*)?Chapter\s+(\d+)(?:\s*[:\-]\s*(.*))?$/i
  );

  if (chapterHeading) {
    currentChapter =
      `Chapter ${chapterHeading[1]}` +
      (
        chapterHeading[2]
          ? `: ${cleanText(chapterHeading[2])}`
          : ''
      );
    current.chapter = currentChapter;
    insidePrompt = false;
    continue;
  }

  const characterField = line.match(
    /^(?:[•>*\-]\s*)*(?:\*\*)?\s*Character\s*(?:\*\*)?\s*:\s*(.*)$/i
  );

  if (characterField) {
    current.character = cleanText(characterField[1]);
    insidePrompt = false;
    continue;
  }

  const promptField = line.match(
    /^(?:[•>*\-]\s*)*(?:\*\*)?\s*Image\s+prompt\s*(?:\*\*)?\s*:\s*(.*)$/i
  );

  if (promptField) {
    current.prompt = cleanText(promptField[1]);
    insidePrompt = true;
    continue;
  }

  const ignoredField = line.match(
    /^(?:[•>*\-]\s*)*(?:\*\*)?\s*(Narration covered|What the image should show)\s*(?:\*\*)?\s*:/i
  );

  if (ignoredField) {
    insidePrompt = false;
    continue;
  }

  if (insidePrompt) {
    const continuation = cleanText(line);
    if (continuation) {
      current.prompt +=
        (current.prompt ? ' ' : '') +
        continuation;
    }
  }
}

saveCurrentScene();

if (rows.length === 0) {
  throw new Error(
    'No scenes were found in the Image Prompt Generator output.'
  );
}

function csvEscape(value) {
  if (value === null || value === undefined) {
    return '""';
  }

  const text = String(value)
    .replace(/\r?\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  return `"${text.replace(/"/g, '""')}"`;
}

const headers = ['chapter', 'shot', 'character', 'prompt'];

const csvLines = [headers.map(csvEscape).join(',')];

for (const row of rows) {
  csvLines.push([
    row.chapter,
    row.shot,
    row.character,
    row.prompt
  ].map(csvEscape).join(','));
}

const csvContent =
  '\uFEFF' +
  csvLines.join('\r\n');


// ============================================================
// SAVE CSV (lock-safe)
// ============================================================

const csvResult = safeWriteFile(projectPath, 'image_prompt', '.csv', csvContent, { encoding: 'utf8' });


// ============================================================
// RETURN RESULT
// ============================================================

return [
  {
    json: {
      topic,
      project_name: data.project_name,
      project_path: projectPath,

      script_filename: scriptResult.filename,
      image_filename: csvResult.filename,

      script_path: scriptResult.path,
      image_csv_path: csvResult.path,

      script_fallback_used: scriptResult.usedFallback,
      image_fallback_used: csvResult.usedFallback,

      scene_count: rows.length,

      status: 'Files saved successfully'
    }
  }
];
